import json
from itertools import permutations

# People are coded by nationality: KR=South Korea, FR=France, GB=Britain, DE=Germany.
PEOPLE = ("KR", "FR", "GB", "DE")

# Languages each person speaks, taken from their own statements (own language plus claimed ones).
# KR claims no foreign languages; FR claims German; GB claims Korean; DE claims all four.
LANG = {
    "KR": {"KR"},
    "FR": {"FR", "DE"},
    "GB": {"GB", "KR"},
    "DE": {"KR", "FR", "GB", "DE"},
}

OPTIONS = {
    "A": ("GB", "DE", "KR", "FR"),
    "B": ("FR", "GB", "DE", "KR"),
    "C": ("DE", "GB", "FR", "KR"),
    "D": ("DE", "GB", "KR", "FR"),
}
NAME = {"KR": "South Korea", "FR": "France", "GB": "Britain", "DE": "Germany"}


def solve():
    solutions = []
    for order in permutations(PEOPLE):  # order[i] lives in room i+1
        room = {p: i + 1 for i, p in enumerate(order)}

        def neighbors(p):
            return [q for q in PEOPLE if q != p and abs(room[q] - room[p]) == 1]

        def talks(p, q):
            # Two people can communicate when they share at least one language.
            return bool(LANG[p] & LANG[q])

        # Korean: my room number is larger than the German's; speaks no foreign
        # language; communicates with no neighbor.
        kr_ok = (
            room["KR"] > room["DE"]
            and LANG["KR"] == {"KR"}
            and not any(talks("KR", q) for q in neighbors("KR"))
        )
        # French: speaks German; communicates with no neighbor.
        fr_ok = (
            "DE" in LANG["FR"]
            and not any(talks("FR", q) for q in neighbors("FR"))
        )
        # British: speaks Korean; communicates with exactly one neighbor.
        gb_ok = (
            "KR" in LANG["GB"]
            and sum(1 for q in neighbors("GB") if talks("GB", q)) == 1
        )
        # German: speaks the languages of all four countries.
        de_ok = LANG["DE"] == set(PEOPLE)

        if kr_ok and fr_ok and gb_ok and de_ok:
            solutions.append(room)

    if len(solutions) != 1:
        return {"final_answer": "UNSUPPORTED",
                "evidence": {"solution_count": len(solutions)}}

    room = solutions[0]
    by_room = sorted(PEOPLE, key=lambda p: room[p])
    order_tuple = tuple(by_room)

    letter = next((k for k, v in OPTIONS.items() if v == order_tuple), None)
    if letter is None:
        return {"final_answer": "UNSUPPORTED",
                "evidence": {"ordering": [NAME[p] for p in by_room]}}

    return {
        "final_answer": f"{letter}. " + ", ".join(NAME[p] for p in by_room),
        "evidence": {
            "solution_count": 1,
            "room_numbers": {NAME[p]: room[p] for p in PEOPLE},
            "ordering_smallest_to_largest": [NAME[p] for p in by_room],
        },
    }


if __name__ == "__main__":
    print(json.dumps(solve()))
